"""Configuration loading for the terminal browser.

The small Hjson reader accepts JSON as well as newline separated, unquoted
configuration entries.  Imports are resolved relative to the declaring file.
"""
import json
import os
import re
import shlex
from pathlib import Path


class ConfigError(Exception):
    pass


def quote(value):
    return json.dumps(str(value), ensure_ascii=False)


def io_error(exc):
    return f'IO Error : {exc.strerror or str(exc)} (os error {exc.errno})'


class HjsonReader:
    def __init__(self, text):
        self.text = text
        self.i = 0
        self.positions = {}
        self.ends = {}

    def skip(self, commas=True):
        s = self.text
        while self.i < len(s):
            if s[self.i].isspace() or (commas and s[self.i] == ','):
                self.i += 1
            elif s[self.i] == '#' or s.startswith('//', self.i):
                j = s.find('\n', self.i)
                self.i = len(s) if j < 0 else j + 1
            elif s.startswith('/*', self.i):
                j = s.find('*/', self.i + 2)
                self.i = len(s) if j < 0 else j + 2
            else:
                break

    def loc(self, pos):
        return self.text.count('\n', 0, pos) + 1, pos - self.text.rfind('\n', 0, pos)

    def fail(self, kind, pos=None):
        pos = self.i if pos is None else pos
        line, col = self.loc(pos)
        suffix = self.text[pos:pos+40]
        raise ValueError(f'{kind} at {line}:{col} at {quote(suffix)}')

    def string(self):
        start = self.i
        try:
            val, size = json.JSONDecoder().raw_decode(self.text[start:])
            self.i += size
            return val
        except (ValueError, json.JSONDecodeError):
            self.fail('InvalidUnicodeCodePoint')

    def value(self, key=()):
        self.skip()
        self.positions[key] = self.i
        if self.i == len(self.text):
            self.fail('Eof')
        c = self.text[self.i]
        if c == '{':
            result = self.obj(key)
        elif c == '[':
            self.i += 1
            result = []
            while True:
                self.skip()
                if self.i >= len(self.text): self.fail('Eof')
                if self.text[self.i] == ']':
                    self.i += 1
                    break
                result.append(self.value(key + (len(result),)))
        elif c == '"':
            result = self.string()
        elif self.text.startswith("'''", self.i):
            self.i += 3
            end = self.text.find("'''", self.i)
            if end < 0: self.fail('Eof')
            result = self.text[self.i:end]
            if result.startswith('\n'): result = result[1:]
            self.i = end + 3
        else:
            m = re.match(r'(true|false|null|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)(?=\s|[\]},]|$)', self.text[self.i:])
            if m:
                word = m.group(1)
                result = json.loads(word)
                self.i += len(word)
            else:
                end = self.text.find('\n', self.i)
                if end < 0: end = len(self.text)
                result = self.text[self.i:end].rstrip('\r ').strip()
                self.i = end
        self.ends[key] = self.i
        return result

    def obj(self, key=(), root=False):
        result = {}
        braced = self.i < len(self.text) and self.text[self.i] == '{'
        if braced: self.i += 1
        while True:
            self.skip()
            if self.i >= len(self.text):
                if braced: self.fail('Eof')
                return result
            if braced and self.text[self.i] == '}':
                self.i += 1
                return result
            if self.text[self.i] == '"':
                name = self.string()
                self.skip(False)
            else:
                start = self.i
                while self.i < len(self.text) and self.text[self.i] not in ':\n{}[]':
                    if self.text[self.i].isspace():
                        # Spaces between a key and its colon are permitted.
                        j = self.i
                        while j < len(self.text) and self.text[j] in ' \t': j += 1
                        if j < len(self.text) and self.text[j] == ':': self.i = j; break
                        self.i = j
                        self.fail('ExpectedMapColon')
                    self.i += 1
                name = self.text[start:self.i].strip()
            if self.i >= len(self.text): self.fail('Eof')
            if self.text[self.i] != ':': self.fail('ExpectedMapColon')
            self.i += 1
            result[name] = self.value(key + (name,))

    def read(self):
        self.skip()
        if self.i == len(self.text): return {}
        return self.obj(root=True)


def simple_toml(text):
    """Fallback for systems predating Python's tomllib."""
    root = {}; current = root
    def split_top(s, delimiter=','):
        parts=[];start=0;depth=0;quoted=None;escaped=False
        for i,c in enumerate(s):
            if escaped: escaped=False; continue
            if quoted:
                if c=='\\' and quoted=='"': escaped=True
                elif c==quoted: quoted=None
            elif c in '\"\'': quoted=c
            elif c in '[{': depth+=1
            elif c in ']}': depth-=1
            elif c==delimiter and depth==0: parts.append(s[start:i].strip());start=i+1
        parts.append(s[start:].strip());return parts
    def value(s):
        s=s.strip()
        if not s: raise ValueError('expected value')
        if s.startswith('"'): return json.loads(s)
        if s.startswith("'"): return s[1:-1]
        if s.startswith('['): return [value(x) for x in split_top(s[1:-1]) if x]
        if s.startswith('{'):
            d={}
            for x in split_top(s[1:-1]):
                k,v=x.split('=',1);d[k.strip().strip('\"\'')]=value(v)
            return d
        if s=='true': return True
        if s=='false': return False
        try: return int(s.replace('_',''))
        except ValueError:
