class HjsonReader:
    def __init__(self, text):
        self.text = text
        self.i = 0
        self.positions = {}
        self.ends = {}

    def skip(self, commas=True):
        s = self.text
        while self.i < len(s):
            if s[self.i].isspace() or (commas and s[self.i] == ','):
                self.i += 1
            elif s[self.i] == '#' or s.startswith('//', self.i):
                j = s.find('\n', self.i)
                self.i = len(s) if j < 0 else j + 1
            elif s.startswith('/*', self.i):
                j = s.find('*/', self.i + 2)
                self.i = len(s) if j < 0 else j + 2
            else:
                break

    def loc(self, pos):
        return self.text.count('\n', 0, pos) + 1, pos - self.text.rfind('\n', 0, pos)

    def fail(self, kind, pos=None):
        pos = self.i if pos is None else pos
        line, col = self.loc(pos)
        suffix = self.text[pos:pos+40]
        raise ValueError(f'{kind} at {line}:{col} at {quote(suffix)}')

    def string(self):
        start = self.i
        try:
            val, size = json.JSONDecoder().raw_decode(self.text[start:])
            self.i += size
            return val
        except (ValueError, json.JSONDecodeError):
            self.fail('InvalidUnicodeCodePoint')

    def value(self, key=()):
        self.skip()
