        if c == '{':
            result = self.obj(key)
        elif c == '[':
            self.i += 1
            result = []
            while True:
                self.skip()
                if self.i >= len(self.text): self.fail('Eof')
                if self.text[self.i] == ']':
                    self.i += 1
