import difflib
import errno
import os
import pkgutil
import re
import shlex
import sys
from pathlib import Path
from .config import quote, io_error
from .ui_data import HELP_TEXT, SHELL_FUNCTIONS

FLAG_NAMES = '''help version dates no-dates only-folders no-only-folders show-root-fs show-git-info no-show-git-info git-status hidden no-hidden git-ignored no-git-ignored permissions no-permissions sizes no-sizes sort-by-count sort-by-date sort-by-size sort-by-type no-tree tree sort-by-type-dirs-first sort-by-type-dirs-last no-sort whale-spotting no-whale-spotting trim-root no-trim-root install listen-auto get-root'''.split()
VALUE_NAMES = {'conf':'paths','max-depth':'MAX_DEPTH','outcmd':'path','verb-output':'verb-output','cmd':'cmd','color':'color','height':'height','set-install-state':'state','print-shell-function':'shell','listen':'socket','write-default-conf':'path','send':'socket'}
