class CliError(Exception):
    pass


def spec(key):
    return '--'+key+((' <'+VALUE_NAMES[key]+'>') if key in VALUE_NAMES else '')


def parse(args, prog='executable'):
    result = {}; root=None; seen=[]; i=0; literal=False
    def usage(suggest=None, duplicates=False):
        keys=[] if duplicates else seen[:]
        if suggest and suggest not in keys: keys.append(suggest)
        if not keys:
            s='[OPTIONS]'
        else:
            s=' '.join(spec(k) for k in keys)
        return f'Usage: {prog} {s} [ROOT]\n'
    def unexpected(arg, suggestions=True):
        msg=f"error: unexpected argument '{arg}' found\n\n"
        guess=None
        if arg.startswith('--') and suggestions:
            opts=FLAG_NAMES+list(VALUE_NAMES)
            key=arg[2:]
            pref=[x for x in opts if x.startswith(key) and len(key)>2]
            if pref: guess=min(pref,key=len)
            else:
                matches=difflib.get_close_matches(key,opts,1,0.72)
                if matches: guess=matches[0]
            if guess:
                msg+=f"  tip: a similar argument exists: '--{guess}'\n\n"
        if arg.startswith('-') and guess is None:
            msg+=f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
        raise CliError(msg+usage(guess))
    def add(key,value=True):
        if key in result:
            raise CliError(f"error: the argument '{spec(key)}' cannot be used multiple times\n\n"+usage(duplicates=True))
        if key in ('height','max-depth'):
            bad=None
            if value=='': bad='cannot parse integer from empty string'
            elif not re.fullmatch(r'\+?\d+',value): bad='invalid digit found in string'
            else:
                num=int(value)
                if num>18446744073709551615: bad='number too large to fit in target type'
                elif key=='height' and num>65535: bad=f'{num} is not in 0..=65535'
            if bad: raise CliError(f"error: invalid value '{value}' for '{spec(key)}': {bad}\n")
            value=int(value)
        if key in ('color','set-install-state'):
            possible={'color':['auto','yes','no'],'set-install-state':['undefined','refused','installed']}[key]
            if value not in possible:
                raise CliError(f"error: invalid value '{value}' for '{spec(key)}'\n  [possible values: {', '.join(possible)}]\n")
