def styled_code(s): return '\x1b[48;5;234m\x1b[38;5;250m'+s+'\x1b[49m\x1b[39m'
def styled_italic(s): return '\x1b[38;5;13m\x1b[3m'+s+'\x1b[0m'


def install(clean=True):
    if clean: print('You requested a clean (re)install.')
    shell=Path(os.environ.get('SHELL','/bin/bash')).name
    if shell not in SHELL_FUNCTIONS: shell='bash'
