def git_info(root):
    statuses={};repo='';branch='';plus=minus=0
    def cmd(args):
        return subprocess.run(['git','-C',root]+args,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=4).stdout
    try:
        repo=cmd(['rev-parse','--show-toplevel']).decode().strip()
        if not repo:return statuses,repo,branch,plus,minus
        branch=cmd(['symbolic-ref','--short','HEAD']).decode().strip()
        parts=cmd(['status','--porcelain','--ignored','-z','--untracked-files=all']).split(b'\0')
        skip=False
        for data in parts:
            if skip:skip=False;continue
            if len(data)<4:continue
            statuscode=data[:2].decode(errors='replace');path=os.path.join(repo,os.fsdecode(data[3:]).rstrip('/'))
            char='N' if statuscode=='??' else ('I' if statuscode=='!!' else ('C' if 'U' in statuscode or statuscode in ('AA','DD') else ('M' if 'M' in statuscode else 'O')))
            statuses[path]=char
            p=os.path.dirname(path)
            while p.startswith(repo) and p!=repo:
                if statuses.get(p)!='M' or char=='M':statuses[p]=char
                p=os.path.dirname(p)
            if 'R' in statuscode or 'C' in statuscode:skip=True
        for line in cmd(['diff','--numstat']).decode(errors='replace').splitlines():
            fields=line.split('\t')
            if len(fields)>1:
                try:plus+=int(fields[0]);minus+=int(fields[1])
                except ValueError:pass
    except (OSError,subprocess.TimeoutExpired):pass
    return statuses,repo,branch,plus,minus


