        elif sort=='size':key=lambda n:(-n.size,n.name.casefold())
        elif sort=='count':key=lambda n:(-(0 if n.isdir and n.count==1 else n.count),n.name.casefold())
        elif sort=='date':key=lambda n:(-n.mtime,n.name.casefold())
        else:key=lambda n:n.name.casefold()
        node.children.sort(key=key)

    def limit_depth(self,node,depth):
        if node.depth>=depth and node.parent is not None:
            node.pruned=bool(node.children)
            node.children=[]
        else:
            for c in node.children:self.limit_depth(c,depth)
        if depth==0 and node.parent is None:
            # A zero limit still shows the immediate entries.
            node.children=[n for n in node.children if not(n.isdir and n.pruned and not n.islink) or n.count>2]

    def capacity(self,node):
        return 1+sum(self.capacity(c) for c in node.children)

    def layout(self,node,budget,is_root=False,first=False):
        children=node.children
        node.shown=[]
        if not children:return
