                node.shown.append(Node(node.path,'',node,node.depth+1,synthetic=True,unlisted=remaining))
            return
        node.pruned=False
        allocations=[1]*count
        extra=slots-count
        capacities=[self.capacity(c) for c in children]
        order=list(range(1,count))+[0] if count else []
        # Distribute spare lines between subtrees instead of allowing the first
        # large directory to consume the whole screen.
        while extra>0:
            available=[i for i in order if allocations[i]<capacities[i]]
            if not available:break
            share=max(1,extra//len(available))
            for i in available:
                add=min(share,capacities[i]-allocations[i],extra)
                allocations[i]+=add;extra-=add
