        if p.kind=='help':p.pattern=text;p.input=text;p.view_offset=0;return
        if p.kind in ('preview','fs','stage'):
            p.pattern=text;p.input=text;return
        if text==p.pattern:return
        if p.pattern:p.last_pattern=p.pattern
        p.pattern=text;p.offset=0;p.full_search=False
        self.rebuild(select_best=True)
        p.input=text;self.input_cursor=len(text)
        if p.tree.filter and p.tree.filter.error:self.message=p.tree.filter.error;self.message_error=True
        else:self.message='';self.message_error=False

    def focus(self,path=None,keep=False):
        p=self.panel;sel=self.path()
        if path:
            target=self.expand_path(path,p.root)
            if not os.path.exists(target):
                self.message=f'Not a directory: {target}';self.message_error=True;return
        else:
            target=sel
            if target==p.root:target=os.path.dirname(p.root)
        target=os.path.realpath(target)
        if os.path.isdir(target):
            p.history.append(self.state())
            if p.pattern:p.last_pattern=p.pattern
            p.root=target;p.selected_path=target;p.pattern=p.pattern if keep else '';p.offset=0;p.kind='tree';p.full_search=False
            self.rebuild();p.input=p.pattern
        else:
            p.target=target
            self.open_preview(target)

    def expand_path(self,path,base=None):
        path=path.strip()
        if (path.startswith('"') and path.endswith('"')) or (path.startswith("'") and path.endswith("'")):path=path[1:-1]
        path=re.sub(r'\\([ :])',r'\1',path)
        path=os.path.expanduser(path)
        return os.path.normpath(path if os.path.isabs(path) else os.path.join(base or self.panel.root,path))

    def move(self,delta=None,absolute=None,matches=False):
        p=self.panel
        if p.kind=='help':
            p.view_offset=max(0,p.view_offset+(delta or 0));return
        if p.kind=='preview':
            p.view_offset=max(0,p.view_offset+(delta or 0));return
        if p.kind=='stage':
            nodes=self.staged
            if not nodes:return
            i=nodes.index(p.selected_path) if p.selected_path in nodes else 0
            p.selected_path=nodes[(i+(delta or 0))%len(nodes)] if absolute is None else nodes[absolute];return
        nodes=[n for n in p.tree.nodes if not n.synthetic and (not matches or n.match and n.parent is not None)]
        if not nodes:return
        i=next((i for i,n in enumerate(nodes) if n.path==p.selected_path),-1 if (delta or 0)>0 else 0)
        if absolute is not None:i=absolute if absolute>=0 else len(nodes)+absolute
        else:i=(i+(delta or 0))%len(nodes)
        i=max(0,min(i,len(nodes)-1));p.selected_path=nodes[i].path;self.ensure_visible()
        for other in self.panels:
            if other.kind=='preview':other.target=p.selected_path;other.view_offset=0
        self.message=''

    def split_input(self,text):
        escape=False
        for i,ch in enumerate(text):
            if escape:escape=False;continue
            if ch=='\\':escape=True;continue
            if ch in ' :' and not(ch==':' and (i+1<len(text) and text[i+1]==':' or i>0 and text[i-1]==':')):
                return text[:i],text[i+1:].lstrip(' :'),True
        return text,'',False

    def run_sequence(self,text):
        sep=os.environ.get('BROOT_CMD_SEPARATOR',';') or ';'
        for command in text.split(sep):
            if self.done:break
            self.execute_command(command,batch=True)
            if not self.done:self.render()

    def execute_command(self,text,batch=False):
        self.message='';self.message_error=False
        pattern,verb,has_verb=self.split_input(text)
        if not has_verb:
            if text=='?':self.do('help','');return
            if batch:
                if text:self.set_filter(text)
                return
            if self.panel.kind=='help':return
            self.focus();return
        if pattern:self.set_filter(pattern)
        if not verb:
