        if isinstance(candidate,dict):self.run_custom(candidate,args)
        else:self.do(candidate,args)
        if not self.done and not self.message_error:self.panel.input=self.panel.pattern
        self.input_cursor=len(self.panel.input)

    def applicable(self,v):
        apply=v.get('apply_to','any');path=self.path();directory=os.path.isdir(path)
        if apply=='directory' and not directory:return False
        if apply in ('file','text_file','binary_file') and directory:return False
        if apply in ('text_file','binary_file'):
            try:
                with open(path,'rb') as f:raw=f.read(8192)
                binary=b'\0' in raw
            except OSError:binary=True
            if (apply=='binary_file') != binary:return False
        exts=v.get('extensions')
        if exts and os.path.splitext(path)[1][1:].lower() not in [e.lower() for e in exts]:return False
        panels=v.get('panels')
        if panels and {'preview':'preview','tree':'tree','stage':'stage','help':'help','fs':'fs'}[self.panel.kind] not in panels:return False
        return True

    def resolve(self,name,batch=False):
        customs=[]
        for v in self.custom:
            inv=v.get('invocation','').split(' ')[0]
            vn=v.get('name',inv) or inv
            shortcut=v.get('shortcut','')
            if name in (inv,vn,shortcut) and name and self.applicable(v):return v
            if any(s and s.startswith(name) for s in (inv,vn,shortcut)) and self.applicable(v):customs.append(v)
        if name in self.aliases:result=self.aliases[name]
        elif name in self.builtin_names:result=name
        else:
            builtin=set(k for k in self.builtin_names if k.startswith(name))
            builtin.update(v for k,v in self.aliases.items() if k.startswith(name))
            if len(builtin)+len(customs)==1:return customs[0] if customs else next(iter(builtin))
            msg=(f'Ambiguous name: More than one verb matches {quote(name)}' if builtin or customs else f'No verb matches {quote(name)}')
            if batch:raise AppError(msg)
            self.message=('ambiguous verb: ' if builtin or customs else 'verb not found: ')+quote(name);self.message_error=True;return None
        if result=='cd' and not os.path.isdir(self.path()):
            self.message='verb not found: '+quote(name);self.message_error=True;return None
        if result=='print_tree' and self.panel.kind!='tree':
            self.message='verb not found: '+quote(name);self.message_error=True;return None
        return result

    def finish(self,output=None,code=0):
        self.output=output;self.code=code;self.done=True

    def do(self,name,args='',depth=0):
        p=self.panel;f=p.flags;sel=self.path()
        if name=='quit':self.finish();return
        if name in ('print_path','print_relative_path'):
            path=sel if name=='print_path' else os.path.relpath(sel,self.initial_root)
            self.finish(path+'\n');return
        if name=='print_tree':
            width=self.sizes()[self.active][1]
            colors=self.options.get('color')=='yes' or (self.options.get('color','auto')=='auto' and sys.stdout.isatty())
            self.finish(self.renderer.export(p.tree,width,self.height,self.selected,p.offset,colors));return
        if name=='cd':
            if not self.options.get('outcmd'):
                self.message='this verb needs broot to be launched as br. Try broot --install if necessary.';self.message_error=True;return
            self.write_outcmd('cd '+shlex.quote(sel)+'\n');self.finish();return
        toggles={'toggle_hidden':'hidden','toggle_ignore':'ignored','toggle_files':'only_folders','toggle_git_file_info':'git','toggle_sizes':'sizes','toggle_dates':'dates','toggle_counts':'counts','toggle_perm':'permissions','toggle_trim_root':'trim_root','toggle_tree':'tree','toggle_root_fs':'root_fs','toggle_device_id':'device_id'}
        if name in toggles:
