            self.rebuild();return
        if name=='no_sort':f.sort='';self.rebuild();return
        if name=='apply_flags':
            if not args.isalpha():self.message='Flags must be a sequence of letters';self.message_error=True;return
            try:flags=parse_cli(['-'+args]);f.apply(flags);self.rebuild();self.message='flags applied'
            except CliError:self.message='Flags must be a sequence of letters';self.message_error=True
            return
        if name in ('set_max_depth','unset_max_depth'):
