            else:
                try:f.max_depth=int(args);assert f.max_depth>=0;self.message='max depth updated'
                except (ValueError,AssertionError):self.message='invalid max depth';self.message_error=True;return
            self.rebuild();return
        if name in ('line_down','line_up','next_match','previous_match'):
            self.move(1 if name in ('line_down','next_match') else -1,matches=name in ('next_match','previous_match') and bool(p.pattern));return
        if name in ('select_first','select_last'):
