        if name in ('page_down','page_up'):
            if p.kind in ('help','preview'):p.view_offset=max(0,p.view_offset+(self.height-3)*(1 if name=='page_down' else -1));return
            try:index=next(i for i,n in enumerate(p.tree.nodes) if n.path==sel)
            except StopIteration:index=0
            index=max(0,min(len(p.tree.nodes)-1,index+(self.height-3)*(1 if name=='page_down' else -1)))
            p.selected_path=p.tree.nodes[index].path;self.ensure_visible();return
        if name in ('focus','open_stay','open_stay_filter','open_leave'):
            if name=='open_leave':
                if os.path.isdir(sel):self.do('cd',args)
                else:self.run_external(['xdg-open',sel],leave=True)
                return
            if name=='focus' or os.path.isdir(sel):self.focus(args or None,name=='open_stay_filter')
            elif name=='open_stay':self.run_external(['xdg-open',sel],leave=False)
            return
        if name=='parent':self.focus(os.path.dirname(sel));return
        if name in ('root_up','up_tree'):
            if p.history and p.history[-1][0]==os.path.dirname(p.root):self.restore(p.history.pop())
            else:self.focus(os.path.dirname(p.root))
            return
        if name=='root_down':
            if self.selected.isdir and sel!=p.root:self.focus(sel)
            elif p.history:self.restore(p.history.pop())
            return
        if name in ('escape','back'):
            if p.kind=='help':p.kind='tree';p.pattern='';p.input='';return
            if p.kind=='preview' and len(self.panels)>1:self.close_panel();return
            if p.input!=p.pattern:p.input=p.pattern;return
            if p.pattern:self.set_filter('');return
            if p.history:self.restore(p.history.pop());return
            if name=='escape' and self.config.get('quit_on_last_cancel'):self.finish()
            return
        if name in ('select','show'):
            # These internals receive their argument from a configured execution
            # pattern, not from the default zero-argument invocation.
            return
        if name in ('refresh','toggle_watch'):
            self.rebuild();return
        if name in ('total_search','search_again'):
            if not p.pattern and p.last_pattern:self.set_filter(p.last_pattern)
            p.full_search=True;self.rebuild(select_best=True);return
        if name=='help':p.kind='help';p.pattern='';p.input='';p.view_offset=0;return
        if name in ('open_preview','toggle_preview','close_preview','preview_text','preview_binary','preview_image','preview_tty'):
            previews=[i for i,x in enumerate(self.panels) if x.kind=='preview']
            if previews and name in ('toggle_preview','close_preview'):
                del self.panels[previews[-1]];self.active=min(self.active,len(self.panels)-1)
            elif name!='close_preview':
                self.open_preview(sel)
