                    if pp.kind=='preview':pp.preview_mode=name.replace('preview_','')
            return
        if name in ('panel_right','panel_left','panel_right_no_open','panel_left_no_open'):
            direction=1 if 'right' in name else -1
            other=self.active+direction
            if 0<=other<len(self.panels):self.active=other
            elif not name.endswith('_no_open'):
                q=Panel(p.root,copy.copy(f));q.selected_path=sel;q.pattern=p.pattern
                pos=len(self.panels) if direction>0 else 0;self.panels.insert(pos,q);self.active=pos;self.rebuild(panel=q)
            return
        if name in ('start_end_panel','close_panel_ok','close_panel_cancel'):
            if len(self.panels)>1:self.close_panel()
            elif name=='start_end_panel':self.do('panel_right','')
            return
        if name in ('stage','unstage','toggle_stage','stage_all_files','stage_all_directories','clear_stage'):
            if name=='clear_stage':self.staged=[]
            elif name.startswith('stage_all_'):
                dirs=name.endswith('directories')
                for n in p.tree.nodes[1:]:
                    if not n.synthetic and n.match and n.isdir==dirs and n.path not in self.staged:self.staged.append(n.path)
            elif name=='unstage' or name=='toggle_stage' and sel in self.staged:
                if sel in self.staged:self.staged.remove(sel)
            elif sel not in self.staged:self.staged.append(sel)
            self.staged.sort(key=str.casefold)
            if self.staged:self.open_stage()
            else:
                self.panels=[q for q in self.panels if q.kind!='stage'] or [p];self.active=min(self.active,len(self.panels)-1)
            return
        if name in ('open_staging_area','toggle_staging_area','close_staging_area','focus_staging_area_no_open'):
            found=next((i for i,q in enumerate(self.panels) if q.kind=='stage'),None)
            if name=='focus_staging_area_no_open':
                if found is not None:self.active=found
            elif found is not None and name!='open_staging_area':
                del self.panels[found];self.active=min(self.active,len(self.panels)-1)
            elif name!='close_staging_area':self.open_stage()
            return
        if name in ('clear_output','write_output'):
            dest=self.options.get('verb-output')
            if not dest:
                self.message='No output file defined. Use --verb-output.';self.message_error=True;return
            try:
                if name=='clear_output':Path(dest).write_text('')
                else:
                    previous=Path(dest).read_text() if os.path.exists(dest) else ''
                    with open(dest,'a') as file:
                        if previous:file.write('\n')
                        file.write(args)
            except OSError as e:raise AppError(io_error(e))
            return
        if name in ('mkdir','copy','move','rename','rm','chmod','copy_to_panel','move_to_panel'):
            self.file_operation(name,args);return
        if name=='filesystems':p.kind='fs';p.input='';p.view_offset=0;return
        if name=='mode_input':self.command_mode=False;return
        if name=='mode_command':self.command_mode=True;return
        if name in ('set_syntax_theme','set_panel_width','default_layout','move_panel_divider','open_trash','trash','restore_trashed_file','delete_trashed_file','purge_trash'):
            if name=='trash':self.file_operation('trash',args)
            return
        if name in ('next_dir','previous_dir','next_same_depth','previous_same_depth'):
            nodes=p.tree.nodes;i=next((i for i,n in enumerate(nodes) if n.path==sel),0);step=-1 if name.startswith('previous') else 1
            for a in range(1,len(nodes)+1):
                n=nodes[(i+a*step)%len(nodes)]
                if (n.isdir if name.endswith('dir') else n.depth==nodes[i].depth):p.selected_path=n.path;break
            self.ensure_visible();return

    def write_outcmd(self,text):
        path=self.options.get('outcmd')
        try:
            fd=os.open(path,os.O_WRONLY|os.O_APPEND)
            os.write(fd,text.encode());os.close(fd)
        except OSError as e:raise AppError(io_error(e))

    def file_operation(self,name,args):
        p=self.panel;paths=self.staged[:] if p.kind=='stage' else [self.path()]
        if name!='rm' and name!='trash' and not args and not name.endswith('_to_panel'):
            self.message='missing argument';self.message_error=True;return
        for path in paths:
            closest=path if os.path.isdir(path) else os.path.dirname(path)
            try:
                if name=='mkdir':
                    dest=self.expand_path(args,closest);os.makedirs(dest,exist_ok=True)
                elif name in ('copy','move','rename','copy_to_panel','move_to_panel'):
                    if name.endswith('_to_panel'):
                        other=next((q for q in self.panels if q is not p and q.kind=='tree'),None)
                        if other is None:self.message='No other panel';self.message_error=True;return
                        dest=other.selected_path if os.path.isdir(other.selected_path) else os.path.dirname(other.selected_path)
                    else:dest=self.expand_path(args,os.path.dirname(path))
                    if name=='rename':dest=os.path.join(os.path.dirname(path),args)
                    if name.startswith('copy'):
                        if os.path.isdir(dest):dest=os.path.join(dest,os.path.basename(path))
                        if os.path.isdir(path):shutil.copytree(path,dest,symlinks=True,dirs_exist_ok=True)
                        elif os.path.islink(path):os.symlink(os.readlink(path),dest)
                        else:shutil.copy2(path,dest)
                    else:shutil.move(path,dest)
                elif name=='rm':
                    if os.path.isdir(path) and not os.path.islink(path):shutil.rmtree(path)
                    else:os.unlink(path)
                elif name=='chmod':
                    command=['chmod']+(['-R'] if os.path.isdir(path) else [])+shlex.split(args)+[path]
                    subprocess.run(command,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
                elif name=='trash':
                    trash=Path(os.environ.get('XDG_DATA_HOME',os.path.expanduser('~/.local/share')))/'Trash'/'files'
                    trash.mkdir(parents=True,exist_ok=True);shutil.move(path,str(trash/os.path.basename(path)))
            except OSError as e:self.message=io_error(e);self.message_error=True;return
        if not os.path.isdir(p.root):p.root=os.path.dirname(p.root)
        self.rebuild()

    def groups(self,args='',v=None):
        path=self.path();directory=path if os.path.isdir(path) else os.path.dirname(path)
        name=os.path.basename(path);stem,extension=os.path.splitext(name)
        groups={'file':path,'parent':os.path.dirname(path),'directory':directory,'root':self.panel.root,
                'file-name':name,'file-stem':stem,'file-extension':extension[1:],'file-dot-extension':extension,
                'line':str(self.selected.match_line),'git-root':self.tree.repo,'git-name':os.path.basename(self.tree.repo),'git-branch':self.tree.branch,'other-panel-file':'','other-panel-directory':'','other-panel-parent':''}
        other=next((p for p in self.panels if p is not self.panel and p.kind=='tree'),None)
        if other:
            path2=other.selected_path or other.root
            groups.update({'other-panel-file':path2,'other-panel-parent':os.path.dirname(path2),'other-panel-directory':path2 if os.path.isdir(path2) else os.path.dirname(path2)})
        if v:
            names=re.findall(r'\{([^{}]+)\}',v.get('invocation',''))
            try:values=shlex.split(args)
            except ValueError:values=args.split()
            for i,n in enumerate(names):
                name,_,format=n.partition(':')
                value=values[i] if i<len(values) else ''
                if len(names)==1:value=args.strip().strip('\"\'')
                if format=='path-from-directory':value=self.expand_path(value,directory)
                elif format=='path-from-parent':value=self.expand_path(value,os.path.dirname(path))
                groups[name]=value
        return groups

    def expand(self,text,groups):
        return re.sub(r'\{([^{}]+)\}',lambda m:groups.get(m[1].split(':')[0],''),text)

    def run_custom(self,v,args):
        groups=self.groups(args,v)
        if 'cmd' in v:
            self.run_sequence(self.expand(str(v['cmd']),groups));return
        execution=v.get('internal',v.get('external',v.get('execution','')))
        is_internal='internal' in v or isinstance(execution,str) and execution.startswith(':')
        if is_internal:
            name=str(execution).lstrip(':').split(' ')[0]
            # The built-in receives the invocation's arguments; its descriptive
            # execution pattern does not add positional arguments to them.
            self.do(name,args);return
        if isinstance(execution,list):tokens=[self.expand(str(x),groups) for x in execution]
        else:
            try:tokens=shlex.split(str(execution))
            except ValueError:tokens=str(execution).split()
            tokens=[self.expand(x,groups) for x in tokens]
        expanded=[]
        for token in tokens:
            if re.fullmatch(r'\$[A-Za-z_]\w*',token):expanded.extend(shlex.split(os.environ.get(token[1:],'')))
            else:expanded.append(os.path.expandvars(token))
        if v.get('from_shell'):
            if not self.options.get('outcmd'):
                self.message='this verb needs broot to be launched as br. Try broot --install if necessary.';self.message_error=True;return
            self.write_outcmd(' '.join(shlex.quote(x) for x in expanded)+'\n');self.finish();return
        wd=self.expand(v.get('working_dir','{directory}' if v.get('set_working_dir') else ''),groups)
        self.run_external(expanded,v.get('leave_broot',True),wd or None,v.get('switch_terminal',True))

    def run_external(self,tokens,leave=True,wd=None,switch=True):
        if not tokens:self.message='No executable';self.message_error=True;return
        if switch:self.session.close()
        try:
            proc=subprocess.run(tokens,cwd=wd if wd and os.path.isdir(wd) else None)
            code=proc.returncode
        except OSError as e:
            if leave:raise AppError(io_error(e))
            self.message=io_error(e);self.message_error=True;code=1
        if leave:self.finish(code=code if code>0 else 0)
        else:
            if switch:self.session.start()
            self.rebuild()

    def open_preview(self,path):
        found=next((q for q in self.panels if q.kind=='preview'),None)
        if found:found.target=path;found.view_offset=0
        elif len(self.panels)<3:
            q=Panel(self.panel.root,copy.copy(self.panel.flags),kind='preview',target=path)
            q.tree=self.tree;q.selected_path=path
            self.panels.append(q)
    def open_stage(self):
        if any(q.kind=='stage' for q in self.panels):return
        if len(self.panels)>=3:return
        q=Panel(self.panel.root,copy.copy(self.panel.flags),kind='stage')
        q.tree=self.tree;q.selected_path=self.staged[0] if self.staged else ''
        self.panels.append(q)
    def close_panel(self):
        if len(self.panels)>1:
            del self.panels[self.active];self.active=max(0,self.active-1)
        else:self.do('back','')

    def status(self):
        if self.message:return self.message
        p=self.panel
        if p.input!=p.pattern and self.split_input(p.input)[2]:
            _,text,_=self.split_input(p.input)
            if not text:return 'Type a verb'
            name,_,args=text.partition(' ')
            for row in VERB_HELP:
                if name in (row[0],row[1]):return row[3]
            return 'verb not found: '+quote(name)
        if p.kind=='help':return 'Hit esc to return to the tree, or type a few letters to filter verbs'
        if p.kind=='preview':return 'Hit esc to go back, ? for help, or a few letters to search'
